int l = 0, r = n - 1;
while (l < r) {
    int sum = a[l] + a[r];
    if (sum == target) {
        // 找到解
        break;
    } else if (sum < target) {
        ++l;          // 和太小，只能让左边变大
    } else {
        --r;          // 和太大，只能让右边变小
    }
}

ListNode *slow = head, *fast = head;
while (fast && fast->next) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) {
        // 有环：找入口
        ListNode *p = head;
        while (p != slow) {
            p = p->next;
            slow = slow->next;
        }
        return p;          // 环入口
    }
}
return nullptr;            // 无环

ListNode *prev = nullptr, *cur = head;
while (cur) {
    ListNode *next = cur->next;   // 先存后继
    cur->next = prev;             // 掉头
    prev = cur;                   // 前驱前移
    cur = next;                   // 当前前移
}
return prev;                      // 新头结点

long long cur = a[0], best = a[0];   // 初值取首元素，兼顾全负数
for (int i = 1; i < n; ++i) {
    cur = std::max<long long>(a[i], cur + a[i]);
    best = std::max(best, cur);
}
return best;

std::sort(iv.begin(), iv.end());     // 按左端点升序
std::vector<std::pair<int,int>> res;
for (auto &[l, r] : iv) {
    if (res.empty() || l > res.back().second) {
        res.push_back({l, r});        // 无重叠，开新区间
    } else {
        res.back().second = std::max(res.back().second, r);
    }
}
